var _mk = SLP.books.find(function(b){ return b.id === "mark"; });
if (!_mk) throw new Error("data/canon.js must load before nt-02-mark-luke.js");
(_mk.chapters = _mk.chapters || []).push(
  { n:1, summary:"John the Baptist appears in the wilderness preaching repentance and baptism for the remission of sins, clothed in camel's hair and eating locusts and wild honey, while announcing a mightier one who will baptize with the Holy Ghost. Jesus comes from Nazareth and is baptized; the heavens open, the Spirit descends like a dove, and a voice declares him the beloved Son. After forty days tempted of Satan in the wilderness, he preaches in Galilee that the kingdom of God is at hand and calls fishermen to leave their nets and become fishers of men. In Capernaum he teaches in the synagogue with an authority the scribes lack, expels an unclean spirit, heals Simon's mother-in-law, and after sunset heals crowds brought to the door. Rising before dawn to pray in a solitary place, he says he must preach in other towns, for therefore came he forth, and cleanses a leper he charges to tell no one. The man publishes it everywhere, and crowds come from every quarter.",
    context:"John the Baptist prepares the way in the wilderness, and Jesus begins his Galilean ministry; Mark is traditionally the earliest gospel, drawn from Peter's preaching.",
    keyVerses:[
      { ref:"Mark 1:11", text:"And there came a voice from heaven, saying, Thou art my beloved Son, in whom I am well pleased." },
      { ref:"Mark 1:15", text:"And saying, The time is fulfilled, and the kingdom of God is at hand: repent ye, and believe the gospel." },
      { ref:"Mark 1:17", text:"And Jesus said unto them, Come ye after me, and I will make you to become fishers of men." }
    ],
    takeaway:"Jesus teaches and acts with divine authority, and those who hear him leave everything to follow.",
    quiz:[
      { q:"What did John the Baptist eat while he preached in the wilderness?", choices:["Locusts and wild honey","Bread and dried fish","Figs and goat's milk","Honey and manna"], a:0, why:"Mark 1:6 describes John clothed in camel's hair, eating locusts and wild honey." },
      { q:"What happened after the cleansed leper disobeyed and published his healing everywhere?", choices:["Jesus was welcomed by the priests","Jesus could no longer openly enter into the city and stayed in desert places","Jesus gathered the crowd into the synagogue","The leper was struck with leprosy again"], a:1, why:"Because the man blazed abroad the matter, Jesus could no more openly enter the city, and people came to him from every quarter." },
      { q:"What did the congregation conclude when Jesus commanded the unclean spirit in the synagogue?", choices:["That he was a trained scribe","That the spirit was harmless","That he taught with authority and even the unclean spirits obeyed him","That Peter had driven it out"], a:2, why:"They were amazed, asking what new doctrine this was, since with authority he commanded even unclean spirits." }
    ] },
  { n:2, summary:"When four men cannot carry their paralyzed friend through the crowded house in Capernaum, they uncover the roof and let down the bed before Jesus. Seeing their faith, he forgives the man's sins; scribes silently object that only God can forgive, so Jesus heals the man to prove that the Son of man has power on earth to forgive sins. He calls Levi the tax collector from his toll booth and eats in his house with publicans and sinners, answering critics that the whole need no physician, for he came to call sinners to repentance. Asked why his disciples do not fast, he likens them to wedding guests while the bridegroom is with them, and shows that new cloth and new wine cannot go into old garments and bottles. When Pharisees accuse the disciples of plucking ears of corn on the sabbath, he recalls David eating the shewbread, teaches that the sabbath was made for man, and declares the Son of man Lord also of the sabbath.",
    context:"Jesus teaches and heals in Capernaum and Galilee, drawing objections from scribes and Pharisees about forgiveness, table fellowship, fasting, and the sabbath.",
    keyVerses:[
      { ref:"Mark 2:5", text:"When Jesus saw their faith, he said unto the sick of the palsy, Son, thy sins be forgiven thee." },
      { ref:"Mark 2:17", text:"When Jesus heard it, he saith unto them, They that are whole have no need of the physician, but they that are sick: I came not to call the righteous, but sinners to repentance." },
      { ref:"Mark 2:27", text:"And he said unto them, The sabbath was made for man, and not man for the sabbath:" }
    ],
    takeaway:"Christ forgives sins, calls sinners to repentance, and rules the sabbath that was made for man.",
    quiz:[
      { q:"How many men carried the man sick of the palsy to Jesus?", choices:["Two","Four","Six","Eight"], a:1, why:"Mark 2:3 says the man sick of the palsy was borne of four." },
      { q:"How did Jesus answer those reasoning that only God can forgive sins?", choices:["He called down fire from heaven","He left Capernaum immediately","He healed the man, who rose, took up his bed, and walked out before them all","He quoted the book of Isaiah"], a:2, why:"He healed the man that they may know the Son of man hath power on earth to forgive sins." },
      { q:"What does Jesus's answer about the physician teach about his mission?", choices:["That only the healthy can follow him","That he avoided social gatherings","That taxes should not be collected","That he came to call sinners, not the righteous, to repentance"], a:3, why:"He said the whole need no physician but the sick, and he came not to call the righteous but sinners to repentance." }
    ] },
  { n:3, summary:"In a synagogue Jesus asks whether it is lawful on the sabbath to do good or to do evil, then restores a man's withered hand; the Pharisees respond by plotting with the Herodians to destroy him. Multitudes follow from Galilee, Judaea, Jerusalem, and beyond, and unclean spirits fall before him crying that he is the Son of God, though he charges them not to make him known. On a mountain he ordains twelve to be with him, to preach, and to heal: Simon he names Peter, James and John he names the sons of thunder, and Judas Iscariot is numbered among them. When scribes from Jerusalem charge that he casts out devils through Beelzebub, he answers that a kingdom or a house divided against itself cannot stand, and warns that blasphemy against the Holy Ghost hath never forgiveness. When his mother and brethren send for him, he says that whoever does the will of God is his brother, sister, and mother.",
    context:"In Galilee, opposition from Pharisees and Jerusalem scribes sharpens as Jesus ordains the Twelve and redefines his true family.",
    keyVerses:[
      { ref:"Mark 3:4", text:"And he saith unto them, Is it lawful to do good on the sabbath days, or to do evil? to save life, or to kill? But they held their peace." },
      { ref:"Mark 3:24", text:"And if a kingdom be divided against itself, that kingdom cannot stand." },
      { ref:"Mark 3:35", text:"For whosoever shall do the will of God, the same is my brother, and my sister, and mother." }
    ],
    takeaway:"Doing the will of God binds believers to Christ more closely than blood.",
    quiz:[
      { q:"With whom did the Pharisees take counsel against Jesus after the withered hand was healed?", choices:["The Roman soldiers","The Samaritans","The Herodians","The publicans"], a:2, why:"Mark 3:6 says the Pharisees took counsel with the Herodians how they might destroy him." },
      { q:"Why did Jesus say the scribes' charge against him was absurd?", choices:["Because devils do not exist","Because the scribes lacked learning","Because his disciples outnumbered them","Because a kingdom or house divided against itself cannot stand, so Satan could not cast out Satan"], a:3, why:"He reasoned that if Satan rise up against himself and be divided, he cannot stand, but hath an end." },
      { q:"Whom did Jesus call his brother, sister, and mother?", choices:["His cousins from Nazareth","Those who attended synagogue weekly","Whoever shall do the will of God","Only the twelve apostles"], a:0, why:"Looking on those who sat about him, he said whosoever shall do the will of God is his kin." }
    ] },
  { n:4, summary:"Teaching from a ship by the sea, Jesus gives the parable of the sower, whose seed falls by the wayside, on stony ground, among thorns, and on good soil. Privately he explains it: the sower sows the word, Satan takes it from careless hearts, tribulation offends the rootless, and cares, riches, and lusts choke it, while good ground brings forth thirty, sixty, and an hundredfold. He adds that a candle is lit to be set on a candlestick, that more shall be given to those who hear, and that the kingdom is like seed growing secretly and like a mustard seed that becomes the greatest of herbs. That evening, crossing the sea, he sleeps through a storm that fills the ship. His frightened disciples wake him; he rebukes the wind and says unto the sea, Peace, be still. Then he asks why they were so fearful and had no faith, and they marvel that even the wind and the sea obey him.",
    context:"By the sea of Galilee Jesus teaches crowds in parables, then that evening crosses the lake and stills a storm.",
    keyVerses:[
      { ref:"Mark 4:20", text:"And these are they which are sown on good ground; such as hear the word, and receive it, and bring forth fruit, some thirtyfold, some sixty, and some an hundred." },
      { ref:"Mark 4:39", text:"And he arose, and rebuked the wind, and said unto the sea, Peace, be still. And the wind ceased, and there was a great calm." },
      { ref:"Mark 4:41", text:"And they feared exceedingly, and said one to another, What manner of man is this, that even the wind and the sea obey him?" }
    ],
    takeaway:"The word bears fruit according to the heart that receives it, and Christ's word calms the storm.",
    quiz:[
      { q:"In the parable's explanation, what does the sower sow?", choices:["Money for the poor","Fruit trees","Wheat for the market","The word"], a:3, why:"Jesus told the disciples, The sower soweth the word." },
      { q:"According to the explanation, what chokes the word sown among thorns?", choices:["Wild beasts of the field","The cares of this world, the deceitfulness of riches, and the lusts of other things","Roman taxation","Too little rain"], a:0, why:"The cares of this world, the deceitfulness of riches, and the lusts of other things enter in and choke the word." },
      { q:"What question did Jesus ask the disciples after calming the storm?", choices:["Why they had not bought more bread","Who among them was the greatest","Why are ye so fearful? how is it that ye have no faith?","Whether they wished to return home"], a:1, why:"After the great calm he asked why they were so fearful and how it was that they had no faith." }
    ] },
  { n:5, summary:"In the country of the Gadarenes Jesus meets a wild man tormented by an unclean spirit, dwelling among the tombs and beyond any chain. Asked its name, the spirit answers, Legion: for we are many. At their request the devils enter a herd of about two thousand swine, which rush down a steep place into the sea. The healed man, clothed and in his right mind, begs to stay with Jesus but is sent home to tell his friends what the Lord has done, and he publishes it throughout Decapolis. Crossing back, Jairus, a ruler of the synagogue, pleads for his dying daughter. On the way a woman who has suffered an issue of blood twelve years touches his garment and is healed at once; Jesus feels virtue go out of him and says, Daughter, thy faith hath made thee whole. Then news comes that the child is dead, but Jesus answers, Be not afraid, only believe, raises her with the words Talitha cumi, and asks that she be given something to eat.",
    context:"Jesus frees a demon-possessed man in the Gadarenes, then heals a hemorrhaging woman and raises the daughter of Jairus, a ruler of the synagogue.",
    keyVerses:[
      { ref:"Mark 5:19", text:"Howbeit Jesus suffered him not, but saith unto him, Go home to thy friends, and tell them how great things the Lord hath done for thee, and hath had compassion on thee." },
      { ref:"Mark 5:34", text:"And he said unto her, Daughter, thy faith hath made thee whole; go in peace, and be whole of thy plague." },
      { ref:"Mark 5:36", text:"As soon as Jesus heard the word that was spoken, he saith unto the ruler of the synagogue, Be not afraid, only believe." }
    ],
    takeaway:"Faith reaches the Lord in every situation; fear gives way when we only believe.",
    quiz:[
      { q:"What name did the unclean spirit give when Jesus asked?", choices:["Legion","Beelzebub","Abaddon","Lucifer"], a:0, why:"The spirit answered, My name is Legion: for we are many." },
      { q:"What became of the herd of swine after the devils entered them?", choices:["They kept feeding on the mountain","They were claimed by the villagers","They ran violently down a steep place into the sea and were choked","They stampeded back toward the tombs"], a:2, why:"The herd, about two thousand, ran violently down a steep place into the sea and were choked." },
      { q:"What did Jesus say to Jairus when messengers reported his daughter dead?", choices:["To send for the professional mourners","That nothing more could be done","To prepare the burial quietly","Be not afraid, only believe"], a:3, why:"As soon as Jesus heard the word, he told the ruler of the synagogue, Be not afraid, only believe." }
    ] },
  { n:6, summary:"Jesus is rejected at Nazareth, his own country, where neighbors ask whether this is not the carpenter, the son of Mary; he marvels at their unbelief, healing only a few sick folk there. He sends the twelve out two by two without scrip, bread, or money, to preach repentance, cast out devils, and anoint the sick with oil. A flashback tells of John the Baptist, imprisoned by Herod for condemning his marriage to Herodias and beheaded at the request of her dancing daughter during the king's birthday feast. When the apostles return, crowds outrun them to a desert place, and Jesus, moved with compassion because they were as sheep not having a shepherd, teaches them many things. Five loaves and two fishes feed about five thousand men, with twelve baskets of fragments left over. That night he comes to his toiling disciples walking on the sea, saying, Be of good cheer: it is I; be not afraid, and in Gennesaret all who touch even the border of his garment are made whole.",
    context:"In Galilee, Jesus is rejected at Nazareth, the Twelve are sent out, John the Baptist is beheaded by Herod, and five thousand are fed.",
    keyVerses:[
      { ref:"Mark 6:4", text:"But Jesus said unto them, A prophet is not without honour, but in his own country, and among his own kin, and in his own house." },
      { ref:"Mark 6:34", text:"And Jesus, when he came out, saw much people, and was moved with compassion toward them, because they were as sheep not having a shepherd: and he began to teach them many things." },
      { ref:"Mark 6:50", text:"For they all saw him, and were troubled. And immediately he talked with them, and saith unto them, Be of good cheer: it is I; be not afraid." }
    ],
    takeaway:"Christ has compassion on the crowds and, when we fear, says: Be of good cheer; it is I.",
    quiz:[
      { q:"How much food did the disciples find to feed the multitude?", choices:["Seven loaves and a few fishes","Five loaves and two fishes","One loaf and no fish","Two hundred pennyworth of bread already bought"], a:1, why:"Asked how many loaves they had, the disciples answered, Five, and two fishes." },
      { q:"Why had Herod imprisoned and then beheaded John the Baptist?", choices:["John led an insurrection","John refused to baptize him","For Herodias' sake, because John said it was not lawful to have his brother's wife","John spoke against the temple taxes"], a:2, why:"Herod bound John for Herodias' sake, for John's rebuke of the unlawful marriage." },
      { q:"What does the account of feeding five thousand show?", choices:["That crowds should bring their own supplies","That the Lord's power makes a little suffice for a multitude","That the disciples failed to plan ahead","That Jesus preferred to teach in deserts"], a:0, why:"From five loaves and two fishes all did eat and were filled, and twelve baskets of fragments remained." }
    ] },
  { n:7, summary:"Pharisees and scribes from Jerusalem fault the disciples for eating bread with unwashen hands, against the tradition of the elders. Jesus answers with Isaiah's charge of honoring God with lips while hearts are far off, accuses them of rejecting the commandment of God to keep their own tradition, and gives the example of Corban, a devoted gift used to avoid aiding parents. To the crowd he teaches that nothing entering a man can defile him; the evils proceeding from within the heart are what defile. In the borders of Tyre and Sidon a Greek, a Syrophenician woman, begs him to cast the devil out of her daughter. After his saying about the children's bread, her answer about the dogs under the table eating the children's crumbs draws the response, For this saying go thy way; the devil is gone out of thy daughter. Returning through Decapolis, he heals a deaf man with an impediment in his speech, sighing, Ephphatha, that is, Be opened, and the more he charges silence, the more they publish it.",
    context:"Pharisees from Jerusalem challenge ritual purity, and Jesus ministers to a Syrophenician woman near Tyre and a deaf man in Decapolis.",
    keyVerses:[
      { ref:"Mark 7:6", text:"He answered and said unto them, Well hath Esaias prophesied of you hypocrites, as it is written, This people honoureth me with their lips, but their heart is far from me." },
      { ref:"Mark 7:15", text:"There is nothing from without a man, that entering into him can defile him: but the things which come out of him, those are they that defile the man." },
      { ref:"Mark 7:29", text:"And he said unto her, For this saying go thy way; the devil is gone out of thy daughter." }
    ],
    takeaway:"Purity is a matter of the heart, and humble faith, even a Gentile's, is heard by the Lord.",
    quiz:[
      { q:"What complaint did the Pharisees and scribes bring against the disciples?", choices:["They failed to fast twice weekly","They ate with publicans","They ate bread with unwashen hands","They grieved on the sabbath"], a:2, why:"They found fault because the disciples ate with defiled, that is, unwashen, hands." },
      { q:"What was Corban, as Jesus cited it?", choices:["A gift dedicated to God, used to avoid helping father or mother","A tax owed to Rome","A ceremonial washing of cups","A vow of silence"], a:0, why:"Corban means a gift; by claiming it for God, a man was freed from doing ought for his parents." },
      { q:"What did the Syrophenician woman's reply reveal?", choices:["That she rejected Israel's God","Humble persistence that trusted the Lord's mercy would reach even her","That she doubted Jesus could heal","That she wanted money instead"], a:1, why:"Her answer about the dogs under the table drew the praise, For this saying go thy way; the devil is gone out of thy daughter." }
    ] },
  { n:8, summary:"A multitude with Jesus three days and nothing to eat is fed with seven loaves and a few small fishes; about four thousand eat and are filled, with seven baskets left over. The Pharisees then seek a sign from heaven, and Jesus, sighing deeply, says no sign shall be given this generation. On the boat he warns of the leaven of the Pharisees and of Herod; the disciples reason about having only one loaf, and he recalls the twelve and seven baskets, asking how they still do not understand. At Bethsaida a blind man is healed in two stages, first seeing men as trees walking. Near Caesarea Philippi, Peter confesses, Thou art the Christ. Jesus teaches openly that the Son of man must suffer, be rejected, be killed, and rise after three days. When Peter rebukes him, Jesus answers, Get thee behind me, Satan, and calls all to deny themselves, take up their cross, and follow, asking what it profits to gain the whole world and lose the soul.",
    context:"In Decapolis and near Caesarea Philippi, Jesus feeds four thousand, warns against spiritual blindness, and first teaches his coming death.",
    keyVerses:[
      { ref:"Mark 8:29", text:"And he saith unto them, But whom say ye that I am? And Peter answereth and saith unto him, Thou art the Christ." },
      { ref:"Mark 8:34", text:"And when he had called the people unto him with his disciples also, he said unto them, Whosoever will come after me, let him deny himself, and take up his cross, and follow me." },
      { ref:"Mark 8:36", text:"For what shall it profit a man, if he shall gain the whole world, and lose his own soul?" }
    ],
    takeaway:"Confessing Christ means taking up the cross; the whole world cannot buy back a lost soul.",
    quiz:[
      { q:"How many baskets of fragments were taken up after the four thousand were fed?", choices:["Twelve","Five","Three","Seven"], a:3, why:"After the four thousand ate, they took up of the broken meat that was left seven baskets." },
      { q:"When Jesus warned of the leaven of the Pharisees and of Herod, what did the disciples wrongly conclude?", choices:["That Herod sought their lives","That it was because they had no bread","That they should avoid Jerusalem","That Judas was stealing"], a:1, why:"They reasoned among themselves that it was because they had no bread, and Jesus asked how they did not understand." },
      { q:"What did Jesus say a follower must be willing to do?", choices:["Withdraw to desert places","Seek a sign from heaven first","Deny himself, take up his cross, and follow him","Sell everything and move to Bethsaida"], a:2, why:"Whosoever will come after him must deny himself, take up his cross, and follow him." }
    ] },
  { n:9, summary:"Before Peter, James, and John, Jesus is transfigured on a high mountain, his raiment exceeding white as snow. Moses and Elias appear talking with him, a cloud overshadows them, and a voice says, This is my beloved Son: hear him. Coming down, he explains that Elias is indeed come, as it was written of him. A father whose son has been tormented by a dumb and deaf spirit since childhood, and whom the disciples could not cure, pleads for help; Jesus answers, If thou canst believe, all things are possible to him that believeth, and the father cries, Lord, I believe; help thou mine unbelief. The spirit departs, and Jesus says this kind comes out by nothing but by prayer and fasting. Passing through Galilee, he again foretells his death and resurrection, which they dare not ask about. At Capernaum, he answers a dispute over greatness by taking a child in his arms: whoever would be first shall be last of all, and servant of all, and he warns against offending one of these little ones.",
    context:"Peter, James, and John witness the Transfiguration on a mountain in Galilee; below it Jesus heals a possessed boy and teaches humility.",
    keyVerses:[
      { ref:"Mark 9:7", text:"And there was a cloud that overshadowed them: and a voice came out of the cloud, saying, This is my beloved Son: hear him." },
      { ref:"Mark 9:23", text:"Jesus said unto him, If thou canst believe, all things are possible to him that believeth." },
      { ref:"Mark 9:35", text:"And he sat down, and called the twelve, and saith unto them, If any man desire to be first, the same shall be last of all, and servant of all." }
    ],
    takeaway:"Hear the beloved Son; believing prayer casts out what effort cannot, and greatness is service.",
    quiz:[
      { q:"Which two Old Testament figures appeared talking with Jesus at the Transfiguration?", choices:["Moses and Elias","Abraham and Isaac","David and Solomon","Isaiah and Jeremiah"], a:0, why:"There appeared unto them Elias with Moses, and they were talking with Jesus." },
      { q:"What was the father's plea when Jesus spoke of believing?", choices:["Lord, give me a sign first","Lord, I believe; help thou mine unbelief","Lord, send my son to the priests","Lord, heal him without my faith"], a:1, why:"With tears the father cried out, Lord, I believe; help thou mine unbelief." },
      { q:"How did Jesus answer the disciples' argument about who should be greatest?", choices:["By ranking the apostles by seniority","By promising thrones to the faithful","By teaching that whoever desires to be first shall be last of all, and servant of all","By appointing Peter as chief"], a:2, why:"Sitting down, he taught that if any man desire to be first, the same shall be last of all, and servant of all." }
    ] },
  { n:10, summary:"Asked whether divorce is lawful, Jesus points beyond Moses' concession to creation: God made them male and female, and what God hath joined together let not man put asunder. When children are brought, he blesses them — of such is the kingdom of God. A rich man who has kept the commandments from youth asks how to inherit eternal life; Jesus, loving him, says to sell what he has, give to the poor, and follow, and the man goes away grieved. Jesus warns how hard it is for them that trust in riches to enter the kingdom, yet with God all things are possible, and those who leave all for the gospel's sake receive an hundredfold with persecutions and eternal life. Foretelling his death and resurrection a third time, he answers James and John's bid for the chief seats: the Son of man came to minister and to give his life a ransom for many. At Jericho, blind Bartimaeus is healed and follows Jesus in the way.",
    context:"Journeying through Judaea toward Jerusalem, Jesus teaches on marriage, children, wealth, and service, and heals blind Bartimaeus at Jericho.",
    keyVerses:[
      { ref:"Mark 10:14", text:"But when Jesus saw it, he was much displeased, and said unto them, Suffer the little children to come unto me, and forbid them not: for of such is the kingdom of God." },
      { ref:"Mark 10:27", text:"And Jesus looking upon them saith, With men it is impossible, but not with God: for with God all things are possible." },
      { ref:"Mark 10:45", text:"For even the Son of man came not to be ministered unto, but to minister, and to give his life a ransom for many." }
    ],
    takeaway:"Greatness is service; the Son of man came to minister and to give his life a ransom for many.",
    quiz:[
      { q:"What did the rich man claim about himself?", choices:["He had kept the commandments from his youth","He had given all to the poor already","He was a priest of the temple","He had never heard of Moses"], a:1, why:"He told Jesus, Master, all these have I observed from my youth." },
      { q:"What did James and John ask of Jesus?", choices:["To see the Father","To call down fire on a village","That one might sit on his right hand and the other on his left in his glory","To be spared from persecution"], a:2, why:"They asked to sit, one on his right hand and the other on his left, in his glory." },
      { q:"Why can the rich still be saved though it is hard for them to enter the kingdom?", choices:["Because wealth can buy favor","Because with God all things are possible","Because the standard applies only to apostles","Because the camel proverb was only a joke"], a:3, why:"When the disciples asked who then can be saved, Jesus said, With men it is impossible, but not with God." }
    ] },
  { n:11, summary:"Near Jerusalem, two disciples fetch a colt whereon never man sat, and Jesus rides toward the city as crowds spread garments and branches, crying, Hosanna; Blessed is he that cometh in the name of the Lord. He looks around the temple and withdraws to Bethany for the night. The next morning he curses a fruitless fig tree, then clears the temple, overthrowing the moneychangers' tables and forbidding vessels to be carried through, teaching that God's house should be called of all nations the house of prayer, but they had made it a den of thieves. The scribes and chief priests begin seeking to destroy him. Passing the withered fig tree the next day, Peter points it out, and Jesus answers, Have faith in God: believing prayer can say to a mountain, be removed, and forgiveness of others is required while we pray. In the temple again, when the chief priests, scribes, and elders demand his authority, he counters with a question about whether John's baptism was from heaven or of men, and their evasive answer earns no reply.",
    context:"At Passover in Jerusalem, Jesus rides in from the mount of Olives, cleanses the temple, and is challenged about his authority.",
    keyVerses:[
      { ref:"Mark 11:9", text:"And they that went before, and they that followed, cried, saying, Hosanna; Blessed is he that cometh in the name of the Lord:" },
      { ref:"Mark 11:17", text:"And he taught, saying unto them, Is it not written, My house shall be called of all nations the house of prayer? but ye have made it a den of thieves." },
      { ref:"Mark 11:22", text:"And Jesus answering saith unto them, Have faith in God." }
    ],
    takeaway:"Have faith in God: believing, forgiving prayer moves what unbelief cannot.",
    quiz:[
      { q:"What animal did Jesus ride into Jerusalem?", choices:["A white horse","A camel","A colt whereon never man sat","A donkey carrying burdens"], a:2, why:"The disciples found a colt tied, whereon never man sat, and Jesus sat upon it." },
      { q:"Why would the priests and elders not answer Jesus's question about John's baptism?", choices:["They had forgotten John entirely","They feared arrest by Rome","They believed John was a false prophet","If they said from heaven, he would ask why they did not believe him; if of men, the people would be offended"], a:3, why:"They reasoned that either answer trapped them, since all men counted John a prophet, and answered, We cannot tell." },
      { q:"What did Jesus say must accompany prayer?", choices:["Fasting until sunset","Payment of temple dues","Forgiving, if ye have ought against any","A public witness in the streets"], a:0, why:"When ye stand praying, forgive, that your Father also which is in heaven may forgive you your trespasses." }
    ] },
  { n:12, summary:"Jesus pictures Israel's leaders as husbandmen who beat the vineyard's servants and kill the owner's wellbeloved son to seize the inheritance; the stone the builders rejected has become the head of the corner, and they know the parable is against them. Asked about tribute money, he answers, Render to Caesar the things that are Caesar's, and to God the things that are God's. When Sadducees who deny the resurrection pose a riddle of seven brothers and one widow, he says the risen neither marry nor are given in marriage, and God is not the God of the dead but of the living. Asked for the first commandment of all, he answers: love the Lord thy God with all thy heart, soul, mind, and strength, and thy neighbour as thyself; the scribe who agrees is not far from the kingdom of God. After asking how David can call the Christ Lord, he warns against scribes who love precedence, and commends a poor widow whose two mites in the treasury are more than all, for she gave all her living.",
    context:"During his final week in the Jerusalem temple, Jesus answers the Pharisees, Herodians, and Sadducees and teaches the common people.",
    keyVerses:[
      { ref:"Mark 12:17", text:"And Jesus answering said unto them, Render to Cæsar the things that are Cæsar's, and to God the things that are God's. And they marvelled at him." },
      { ref:"Mark 12:30", text:"And thou shalt love the Lord thy God with all thy heart, and with all thy soul, and with all thy mind, and with all thy strength: this is the first commandment." },
      { ref:"Mark 12:44", text:"For all they did cast in of their abundance; but she of her want did cast in all that she had, even all her living." }
    ],
    takeaway:"Love God with all you are and your neighbour as yourself; God weighs the giver, not the gift.",
    quiz:[
      { q:"Whom did the owner of the vineyard send last of all to the husbandmen?", choices:["A Roman centurion","An angel","Twelve new servants","His wellbeloved son"], a:3, why:"Having one son, his wellbeloved, the lord of the vineyard sent him also last, saying, They will reverence my son." },
      { q:"What did the Sadducees deny that shaped their riddle about the seven brothers?", choices:["That there is any resurrection","That Moses wrote the law","That Caesar should be obeyed","That God created the world"], a:0, why:"The Sadducees, which say there is no resurrection, posed the case of seven brethren and one widow." },
      { q:"Why did Jesus say the poor widow gave more than all the rich?", choices:["Her coins were rarer","The treasury was for widows","She cast in of her want all that she had, even all her living","She came every day to the temple"], a:2, why:"The rich cast in of their abundance, but she of her want cast in all that she had, even all her living." }
    ] },
  { n:13, summary:"Leaving the temple, Jesus tells a marveling disciple that its great buildings will be left with not one stone upon another. From the mount of Olives, Peter, James, John, and Andrew ask when these things will be and what signs will come first. He answers, take heed: false christs will arise, wars and rumours of wars are beginnings of sorrows, and disciples will be delivered to councils and beaten, yet the gospel must first be published among all nations, and the Holy Ghost will speak in them. When the abomination of desolation stands where it ought not, those in Judaea must flee, for the Lord has shortened those days for the elect's sake. After that tribulation the sun and moon are darkened, and the Son of man comes in the clouds with great power and glory to gather his elect. The fig tree's leaves show summer is near; but of that day and hour knoweth no man, neither the Son, but the Father — so watch, for ye know not when the master of the house cometh.",
    context:"On the mount of Olives opposite the temple, Jesus privately answers Peter, James, John, and Andrew about the temple's fall and his coming.",
    keyVerses:[
      { ref:"Mark 13:26", text:"And then shall they see the Son of man coming in the clouds with great power and glory." },
      { ref:"Mark 13:31", text:"Heaven and earth shall pass away: but my words shall not pass away." },
      { ref:"Mark 13:37", text:"And what I say unto you I say unto all, Watch." }
    ],
    takeaway:"Watch and pray through deception and tribulation; Christ will come in power and glory at the appointed hour.",
    quiz:[
      { q:"Which four disciples asked Jesus privately about the signs of the end?", choices:["Peter, James, John, and Andrew","Peter, Andrew, Philip, and Thomas","Peter, Matthew, John, and Jude","Peter, James, Andrew, and Judas"], a:0, why:"On the mount of Olives, Peter and James and John and Andrew asked him privately." },
      { q:"What did Jesus say must first be published among all nations?", choices:["Rome's census records","The writings of the prophets","The gospel","News of the temple's fall"], a:2, why:"Before persecution and desolation, the gospel must first be published among all nations." },
      { q:"Who knows the day and hour of the end, according to Jesus?", choices:["The angels in heaven","The Son also, with the Father","No man, neither the angels nor the Son, but the Father only","Peter and the Twelve together"], a:3, why:"Of that day and hour knoweth no man, no, not the angels which are in heaven, neither the Son, but the Father." }
    ] },
  { n:14, summary:"As the chief priests plot his death two days before the passover, a woman at Bethany pours ointment of spikenard on his head; he defends her, for she has anointed his body to the burying, and her deed will be told wherever the gospel is preached. Judas then bargains with the chief priests. In a furnished upper room Jesus announces that one of the twelve will betray him, and institutes the sacrament: bread blessed and broken, and the cup, this is my blood of the new testament, which is shed for many. He warns that the sheep will be scattered and that Peter will deny him thrice before the cock crow twice. In Gethsemane he is sore amazed, praying, nevertheless not what I will, but what thou wilt, while Peter, James, and John cannot watch one hour. Judas betrays him with a kiss, the disciples flee, and before the high priest Jesus confesses he is the Christ and is condemned to die. Peter, warming himself below, denies him three times, hears the cock crew, remembers, and weeps.",
    context:"In Jerusalem at passover time, Jesus keeps the feast with the twelve, agonizes in Gethsemane, and is betrayed and condemned by night.",
    keyVerses:[
      { ref:"Mark 14:22", text:"And as they did eat, Jesus took bread, and blessed, and brake it, and gave to them, and said, Take, eat: this is my body." },
      { ref:"Mark 14:24", text:"And he said unto them, This is my blood of the new testament, which is shed for many." },
      { ref:"Mark 14:36", text:"And he said, Abba, Father, all things are possible unto thee; take away this cup from me: nevertheless not what I will, but what thou wilt." }
    ],
    takeaway:"In the sacrament we remember the body and blood given for us; Gethsemane shows obedience that costs everything.",
    quiz:[
      { q:"What sign did Judas use to identify Jesus to the mob?", choices:["A silver coin raised high","A trumpet call","A kiss","A lantern held overhead"], a:1, why:"Judas had told the mob, Whomsoever I shall kiss, that same is he, and he greeted Jesus as Master, master, and kissed him." },
      { q:"What did Jesus say the cup represented?", choices:["The passover lamb's blood","Moses' water from the rock","The wine of David's feast","His blood of the new testament, which is shed for many"], a:3, why:"Taking the cup, he gave thanks and said, This is my blood of the new testament, which is shed for many." },
      { q:"What does Jesus's Gethsemane prayer, nevertheless not what I will, but what thou wilt, teach?", choices:["That desire should be hidden from God","That suffering should be sought for itself","That the Father's will rules even when the request is honestly made","That disciples should pray alone at night"], a:0, why:"Even asking that the hour might pass from him, Jesus submitted: nevertheless not what I will, but what thou wilt." }
    ] },
  { n:15, summary:"In the morning the council binds Jesus and delivers him to Pilate. Asked whether he is the King of the Jews, he answers only, Thou sayest it, and his silence amazes Pilate. At the feast Pilate offers to release a prisoner; the crowd, moved by the chief priests, chooses Barabbas, crying, Crucify him. Willing to content the people, Pilate releases Barabbas and delivers scourged Jesus to be crucified. Soldiers robe him in purple, crown him with thorns, and mock him; Simon of Cyrene carries the cross. Crucified at Golgotha between two thieves, under the inscription THE KING OF THE JEWS, he is reviled by passersby, priests, and thieves alike: he saved others, himself he cannot save. Darkness covers the land from the sixth to the ninth hour; then he cries, my God, my God, why hast thou forsaken me, and gives up the ghost. The veil of the temple is rent from top to bottom, a centurion declares, Truly this man was the Son of God, and Joseph of Arimathaea begs the body and lays it in a rock-hewn sepulchre.",
    context:"Condemned by the council, Jesus is crucified at Golgotha under Pilate and buried by Joseph of Arimathaea before the sabbath.",
    keyVerses:[
      { ref:"Mark 15:34", text:"And at the ninth hour Jesus cried with a loud voice, saying, Eloi, Eloi, lama sabachthani? which is, being interpreted, My God, my God, why hast thou forsaken me?" },
      { ref:"Mark 15:39", text:"And when the centurion, which stood over against him, saw that he so cried out, and gave up the ghost, he said, Truly this man was the Son of God." },
      { ref:"Mark 15:43", text:"Joseph of Arimathæa, an honourable counsellor, which also waited for the kingdom of God, came, and went in boldly unto Pilate, and craved the body of Jesus." }
    ],
    takeaway:"The Son of God died at Golgotha; even the centurion watching saw who he was.",
    quiz:[
      { q:"Which prisoner did the crowd ask Pilate to release?", choices:["Simon of Cyrene","Lazarus","Barabbas","An unnamed thief"], a:2, why:"The chief priests moved the people that he should rather release Barabbas, who had committed murder in the insurrection." },
      { q:"What did bystanders misunderstand when Jesus cried, Eloi, Eloi, lama sabachthani?", choices:["They thought he called for Elias","They thought he forgave them","They thought he cursed Rome","They did not hear him at all"], a:0, why:"Some that stood by said, Behold, he calleth Elias, and one offered vinegar to see if Elias would come." },
      { q:"What does the centurion's words at the cross show?", choices:["That even a Roman officer recognized the Son of God in his death","That the soldiers had followed Jesus long","That Pilate ordered the confession","That the centurion feared an earthquake"], a:1, why:"Seeing how Jesus cried out and gave up the ghost, the centurion said, Truly this man was the Son of God." }
    ] },
  { n:16, summary:"At the rising of the sun on the first day of the week, Mary Magdalene, Mary the mother of James, and Salome bring sweet spices to anoint the crucified Jesus, wondering who will roll the great stone from the door. The stone is rolled away, and a young man in a long white garment announces that Jesus of Nazareth, which was crucified, is risen and is not here. He sends them to tell the disciples and Peter that Jesus goes before them into Galilee; trembling and amazed, the women say nothing at first. The risen Lord then appears first to Mary Magdalene, whose report the mourning disciples believe not, then to two walking into the country, also disbelieved, and afterward to the eleven at meat, whom he upbraids for unbelief and hardness of heart. He commissions them, Go ye into all the world, and preach the gospel to every creature, and he that believeth and is baptized shall be saved. He is received up into heaven, and they go forth preaching everywhere, the Lord working with them.",
    context:"On the Sunday after the crucifixion, women find the tomb near Jerusalem empty; the risen Christ then appears to his disciples and ascends.",
    keyVerses:[
      { ref:"Mark 16:6", text:"And he saith unto them, Be not affrighted: Ye seek Jesus of Nazareth, which was crucified: he is risen; he is not here: behold the place where they laid him." },
      { ref:"Mark 16:15", text:"And he said unto them, Go ye into all the world, and preach the gospel to every creature." },
      { ref:"Mark 16:16", text:"He that believeth and is baptized shall be saved; but he that believeth not shall be damned." }
    ],
    takeaway:"He is risen: the risen Christ sends believers into all the world with the gospel.",
    quiz:[
      { q:"Who came to the sepulchre at the rising of the sun with spices?", choices:["Peter and John","The eleven apostles","Joseph of Arimathaea's servants","Mary Magdalene, Mary the mother of James, and Salome"], a:3, why:"When the sabbath was past, these women had bought sweet spices, that they might come and anoint him." },
      { q:"What did the young man in the white garment tell the women to do?", choices:["Tell no man what they had seen","Tell his disciples and Peter that Jesus goes before them into Galilee","Announce the news in the temple","Wait at the tomb for three days"], a:1, why:"The young man said, Go your way, tell his disciples and Peter that he goeth before you into Galilee." },
      { q:"In the commission, what two things did Jesus join together for salvation?", choices:["Fasting and almsgiving","Pilgrimage and sacrifice","Belief and baptism","Repentance and restitution"], a:2, why:"He said, He that believeth and is baptized shall be saved; but he that believeth not shall be damned." }
    ] } );
var _lk = SLP.books.find(function(b){ return b.id === "luke"; });
if (!_lk) throw new Error("data/canon.js must load before nt-02-mark-luke.js");
(_lk.chapters = _lk.chapters || []).push(
  { n:1, summary:"Luke writes to Theophilus an orderly account of things most surely believed. In the days of Herod, the priest Zacharias and his righteous, childless wife Elisabeth receive a temple visitation: the angel Gabriel promises a son named John, filled with the Holy Ghost from his mother's womb, who will go before the Lord in the spirit and power of Elias to make ready a people prepared for him. Because Zacharias doubts, he is left speechless until the day the promise is fulfilled, and Elisabeth conceives. Six months later Gabriel comes to the virgin Mary in Nazareth: she will bear a son named Jesus, called the Son of the Highest, whose kingdom shall have no end. Her answer is faith — Behold the handmaid of the Lord. With Elisabeth she sings of a God who scatters the proud, puts down the mighty, and fills the hungry with good things. When John is born, Zacharias's mouth opens, and his prophecy blesses God for the dayspring from on high.",
    context:"Luke, writing an ordered account to Theophilus, opens in the days of Herod with Gabriel's announcements to Zacharias in the temple and Mary in Nazareth.",
    keyVerses:[
      { ref:"Luke 1:32", text:"He shall be great, and shall be called the Son of the Highest: and the Lord God shall give unto him the throne of his father David:" },
      { ref:"Luke 1:38", text:"And Mary said, Behold the handmaid of the Lord; be it unto me according to thy word. And the angel departed from her." },
      { ref:"Luke 1:46", text:"And Mary said, My soul doth magnify the Lord," }
    ],
    takeaway:"Nothing is impossible with God, and faith answers his word: be it unto me according to thy word.",
    quiz:[
      { q:"What happened to Zacharias because he doubted Gabriel's message?", choices:["He was left unable to speak until the promise was fulfilled","He was struck blind","He lost his priestly office","He was expelled from the temple"], a:0, why:"Because he believed not the words, Zacharias was dumb and not able to speak until the day the things were performed." },
      { q:"In whose spirit and power did Gabriel say John would go before the Lord?", choices:["Moses","Elias","David","Samuel"], a:1, why:"John would go before the Lord in the spirit and power of Elias, to make ready a people prepared for the Lord." },
      { q:"How did Mary answer the angel's announcement?", choices:["With a request for a sign","By telling Joseph at once","Behold the handmaid of the Lord; be it unto me according to thy word","With fear that kept her silent"], a:2, why:"Mary answered, Behold the handmaid of the Lord; be it unto me according to thy word." }
    ] },
  { n:2, summary:"A decree from Caesar Augustus brings Joseph and the pregnant Mary from Nazareth to Bethlehem, where her firstborn son is born and laid in a manger because the inn has no room. Shepherds watching their flocks by night hear good tidings of great joy: unto you is born this day in the city of David a Saviour, which is Christ the Lord. A multitude of the heavenly host praises God, and the shepherds hurry to Bethlehem, find the babe in a manger, and spread the word while Mary ponders these things in her heart. Named Jesus at eight days, the child is presented in the temple, where the waiting Simeon blesses God for a salvation prepared before all people, a light to lighten the Gentiles, and the prophetess Anna gives thanks and speaks of him to all that looked for redemption. At twelve, Jesus lingers three days among the doctors, and answers his seeking mother, Wist ye not that I must be about my Father's business? He increases in wisdom and stature, and in favour with God and man.",
    context:"From the taxing under Caesar Augustus to yearly Passover visits from Nazareth, Luke sets Jesus's birth and childhood in Bethlehem and Jerusalem.",
    keyVerses:[
      { ref:"Luke 2:11", text:"For unto you is born this day in the city of David a Saviour, which is Christ the Lord." },
      { ref:"Luke 2:14", text:"Glory to God in the highest, and on earth peace, good will toward men." },
      { ref:"Luke 2:52", text:"And Jesus increased in wisdom and stature, and in favour with God and man." }
    ],
    takeaway:"Salvation entered the world in a manger: the Savior grew as children do, in favour with God and man.",
    quiz:[
      { q:"Where was the newborn Jesus laid?", choices:["On the temple steps","In a manger","In a guest chamber","In Simeon's arms"], a:1, why:"She wrapped him in swaddling clothes and laid him in a manger, because there was no room in the inn." },
      { q:"What promise had the Holy Ghost made to Simeon?", choices:["That he would see the temple rebuilt","That he would not see death before he had seen the Lord's Christ","That Israel would defeat Rome","That his descendants would be prophets"], a:2, why:"It was revealed unto Simeon by the Holy Ghost that he should not see death before he had seen the Lord's Christ." },
      { q:"What did Simeon's blessing say the child was prepared to be?", choices:["A military deliverer for Judaea only","A teacher of the law in Jerusalem","A king over Rome","A light to lighten the Gentiles, and the glory of thy people Israel"], a:3, why:"Simeon blessed God for salvation prepared before the face of all people, a light to lighten the Gentiles and the glory of Israel." }
    ] },
  { n:3, summary:"In the fifteenth year of Tiberius Caesar the word of God comes to John, who preaches the baptism of repentance throughout the country about Jordan. To the crowds he is blunt: bring forth fruits worthy of repentance, and do not claim Abraham as father, for every fruitless tree is hewn down. Asked what to do, he tells the people to share coats and food, the publicans to exact no more than appointed, and the soldiers to do no violence, accuse none falsely, and be content with their wages. When people wonder whether John himself is the Christ, he points to one mightier, who will baptize with the Holy Ghost and with fire. Because John reproves Herod for Herodias, he is shut up in prison. Then Jesus also is baptized; as he prays, the heaven opens, the Holy Ghost descends like a dove, and a voice names him the beloved Son. The chapter closes with his genealogy traced through David and Abraham back to Adam, the son of God.",
    context:"By the Jordan in the fifteenth year of Tiberius Caesar, John preaches repentance and baptizes Jesus, whose lineage Luke traces to Adam.",
    keyVerses:[
      { ref:"Luke 3:8", text:"Bring forth therefore fruits worthy of repentance, and begin not to say within yourselves, We have Abraham to our father: for I say unto you, That God is able of these stones to raise up children unto Abraham." },
      { ref:"Luke 3:16", text:"John answered, saying unto them all, I indeed baptize you with water; but one mightier than I cometh, the latchet of whose shoes I am not worthy to unloose: he shall baptize you with the Holy Ghost and with fire:" },
      { ref:"Luke 3:22", text:"And the Holy Ghost descended in a bodily shape like a dove upon him, and a voice came from heaven, which said, Thou art my beloved Son; in thee I am well pleased." }
    ],
    takeaway:"Repentance shows in conduct, and points beyond itself to Christ, who baptizes with the Holy Ghost and fire.",
    quiz:[
      { q:"What counsel did John give the publicans who came to be baptized?", choices:["To abandon their posts","To give half their goods to the poor","To exact no more than that which is appointed them","To refuse coins bearing Caesar's image"], a:2, why:"To the publicans John said, Exact no more than that which is appointed you." },
      { q:"What happened to John because he reproved Herod?", choices:["He was made a priest in the temple","Herod repented before him","The people shielded him","He was shut up in prison"], a:3, why:"Because John reproved Herod for Herodias and other evils, Herod shut up John in prison." },
      { q:"Why does Luke trace Jesus's genealogy to Adam rather than stopping at Abraham?", choices:["To date his birth precisely","To show his royal priesthood","To connect the Son of God with all humanity","To replace the law of Moses"], a:0, why:"The lineage runs through David and Abraham to Adam, which was the son of God, joining the Lord to all mankind." }
    ] },
  { n:4, summary:"Full of the Holy Ghost, Jesus is led into the wilderness, where he fasts forty days and is tempted of the devil. Offered bread, the kingdoms of the world, and a leap from the temple's pinnacle, he answers every time with scripture: man shall not live by bread alone, and God alone is to be worshipped and served. The devil departs for a season. In Nazareth he reads Isaiah's words about the Spirit-anointed servant sent to preach the gospel to the poor, heal the brokenhearted, and set at liberty the bruised, and announces, This day is this scripture fulfilled in your ears. When hearers marvel only at Joseph's son, he observes that no prophet is accepted in his own country, citing the widow of Sarepta and Naaman the Syrian; enraged, the congregation tries to cast him from a hill, but he passes through them. In Capernaum his word carries power: an unclean spirit is cast out, Simon's wife's mother is healed, and he must preach the kingdom of God to other cities also.",
    context:"After fasting in the wilderness, Jesus teaches in the synagogue at Nazareth and then ministers with power in Capernaum of Galilee.",
    keyVerses:[
      { ref:"Luke 4:4", text:"And Jesus answered him, saying, It is written, That man shall not live by bread alone, but by every word of God." },
      { ref:"Luke 4:18", text:"The Spirit of the Lord is upon me, because he hath anointed me to preach the gospel to the poor; he hath sent me to heal the brokenhearted, to preach deliverance to the captives, and recovering of sight to the blind, to set at liberty them that are bruised," },
      { ref:"Luke 4:43", text:"And he said unto them, I must preach the kingdom of God to other cities also: for therefore am I sent." }
    ],
    takeaway:"Scripture arms the believer against temptation; Christ's mission is good news for the poor and liberty for the broken.",
    quiz:[
      { q:"What was the devil's first temptation in the wilderness?", choices:["To worship him for the kingdoms","To cast himself from the temple pinnacle","To reveal his glory to Israel","To command that a stone be made bread"], a:3, why:"The devil first said, If thou be the Son of God, command this stone that it be made bread." },
      { q:"Which two Old Testament figures did Jesus cite as recipients of God's favor outside Israel?", choices:["Solomon and Jonah","The widow of Sarepta and Naaman the Syrian","Adam and Abraham","Ruth and Boaz"], a:0, why:"He cited the widow of Sarepta aided by Elias and Naaman the Syrian cleansed by Eliseus." },
      { q:"How did Jesus meet every temptation?", choices:["By performing a miracle","With the written word, It is written","By ignoring the devil","By calling twelve angels"], a:1, why:"Each answer began with scripture, and when the temptation ended the devil departed from him for a season." }
    ] },
  { n:5, summary:"Pressing crowds at the lake of Gennesaret lead Jesus to teach from Simon's ship. Afterwards he tells the fisherman, who has toiled all night and taken nothing, to launch into the deep and let down the nets. The draught fills both ships to sinking; Peter falls at Jesus' knees as a sinful man, but hears, Fear not; from henceforth thou shalt catch men, and with James and John forsakes all. Jesus cleanses a leper, then heals a man sick of the palsy whose friends let him down through the tiling of a packed house; seeing their faith, he first forgives the man's sins, then heals him to show that the Son of man hath power upon earth to forgive sins. He calls Levi the publican, who makes a great feast; when critics murmur at his eating with publicans and sinners, he answers that they that are whole need not a physician — he came not to call the righteous, but sinners to repentance. Questions about fasting draw the picture of the bridegroom and of new wine old bottles cannot hold.",
    context:"At the lake of Gennesaret and in Galilee, Jesus calls fishermen and Levi, heals an outcast leper and a paralytic, and defends eating with sinners.",
    keyVerses:[
      { ref:"Luke 5:10", text:"And so was also James, and John, the sons of Zebedee, which were partners with Simon. And Jesus said unto Simon, Fear not; from henceforth thou shalt catch men." },
      { ref:"Luke 5:24", text:"But that ye may know that the Son of man hath power upon earth to forgive sins, (he said unto the sick of the palsy,) I say unto thee, Arise, and take up thy couch, and go into thine house." },
      { ref:"Luke 5:32", text:"I came not to call the righteous, but sinners to repentance." }
    ],
    takeaway:"Christ calls the ashamed to leave everything and catch men with him.",
    quiz:[
      { q:"What did Peter say when he saw the miraculous draught?", choices:["He fell down at Jesus' knees, saying, Depart from me; for I am a sinful man, O Lord","He offered to buy Jesus a new boat","He laughed at the impossible catch","He demanded a sign before following"], a:0, why:"When Simon Peter saw it, he fell down at Jesus' knees, confessing himself a sinful man." },
      { q:"How did the friends of the man sick of the palsy get him to Jesus?", choices:["They waited for the crowd to leave","They carried him to the synagogue","They went upon the housetop and let him down through the tiling","They sent for the priests first"], a:2, why:"Unable to get through the multitude, they went upon the housetop and let him down through the tiling with his couch." },
      { q:"What lesson does the miraculous catch teach about following Jesus?", choices:["That skill guarantees success","That fishing was a wasted trade","That crowds always bring miracles","At his word, obedience brings what effort alone cannot — and they forsook all"], a:3, why:"After a fruitless night, nets let down at Jesus' word filled both ships, and the fishermen forsook all and followed him." }
    ] },
  { n:6, summary:"Two sabbath controversies open the chapter: plucking ears of corn on the sabbath, then a withered hand healed after Jesus asks whether it is lawful to do good or evil on the sabbath day; his enemies fill with madness, for he is Lord also of the sabbath. In a mountain he continues all night in prayer to God, then chooses twelve whom he names apostles. Coming down to a plain, he heals a great multitude from Judaea and Jerusalem, and preaches: blessed are the poor, the hungry, those who weep, and those hated for the Son of man's sake, while woes fall on the rich and the self-satisfied. Then the kingdom's ethic — love your enemies, do good to them that hate you, and as ye would that men should do to you, do ye also to them likewise; be ye therefore merciful, as your Father also is merciful. Judge not, forgive, and give; a tree is known by its fruit, and only he who hears and does Christ's sayings builds a house upon a rock.",
    context:"On a plain before crowds from Judaea, Jerusalem, and the coasts, Jesus chooses the Twelve and preaches the sermon on the plain.",
    keyVerses:[
      { ref:"Luke 6:31", text:"And as ye would that men should do to you, do ye also to them likewise." },
      { ref:"Luke 6:36", text:"Be ye therefore merciful, as your Father also is merciful." },
      { ref:"Luke 6:46", text:"And why call ye me, Lord, Lord, and do not the things which I say?" }
    ],
    takeaway:"Mercy marks the Master's disciples: love enemies, judge not, and do what the Lord says.",
    quiz:[
      { q:"How long did Jesus pray on the mountain before choosing the twelve?", choices:["Until sunset","About one hour","Three days","All night"], a:3, why:"He went out into a mountain to pray, and continued all night in prayer to God." },
      { q:"Whom did Jesus call blessed at the start of the sermon?", choices:["The rich and the full","The poor, the hungry, those who weep, and those hated for the Son of man's sake","The scribes and Pharisees","Only the twelve apostles"], a:1, why:"He blessed the poor, the hungry, those who weep, and those hated and cast out for the Son of man's sake." },
      { q:"What did Jesus compare the one who hears his sayings and does them to?", choices:["A merchant seeking pearls","A tree planted by water","A soldier guarding a city","A man who built a house and laid the foundation on a rock"], a:0, why:"The hearer who does is like a man who dug deep and founded his house on a rock, which the flood could not shake." }
    ] },
  { n:7, summary:"In Capernaum a centurion's beloved servant lies near death. The humble officer sends word that he is unworthy to receive Jesus under his roof: say in a word, and my servant shall be healed, for he too knows what authority means. Jesus marvels — not so great faith found in Israel — and the servant is made whole. At Nain he meets a funeral: the only son of a widow. Moved with compassion, he touches the bier and raises the young man, delivering him to his mother, and the people glorify God. In prison, John the Baptist sends two disciples to ask whether Jesus is he that should come; Jesus answers with the blind who see, the lame who walk, lepers cleansed, the dead raised, and the gospel preached to the poor, and praises John as more than a prophet. At a Pharisee's table a weeping woman washes his feet with tears; the parable of two forgiven debtors shows why her love is great, and he says, Thy faith hath saved thee; go in peace.",
    context:"In Galilee, Jesus heals a centurion's servant, raises the widow of Nain's son, and answers the question of John the Baptist's messengers.",
    keyVerses:[
      { ref:"Luke 7:9", text:"When Jesus heard these things, he marvelled at him, and turned him about, and said unto the people that followed him, I say unto you, I have not found so great faith, no, not in Israel." },
      { ref:"Luke 7:22", text:"Then Jesus answering said unto them, Go your way, and tell John what things ye have seen and heard; how that the blind see, the lame walk, the lepers are cleansed, the deaf hear, the dead are raised, to the poor the gospel is preached." },
      { ref:"Luke 7:50", text:"And he said to the woman, Thy faith hath saved thee; go in peace." }
    ],
    takeaway:"Great faith is humble; Christ answers doubt with evidence and meets repentant love with forgiveness.",
    quiz:[
      { q:"Where did Jesus raise a widow's only son?", choices:["In Bethany","At Capernaum","In the city called Nain","On the mount of Olives"], a:2, why:"At the gate of the city called Nain he raised the only son of the widow and delivered him to his mother." },
      { q:"What impressed Jesus about the centurion?", choices:["His generous donations to the synagogue alone","His humility and confidence that one word from Jesus could heal at a distance","His rank in the Roman army","The size of his household"], a:0, why:"The centurion felt unworthy of a visit and trusted that saying in a word would heal, and Jesus marvelled at his faith." },
      { q:"What does the parable of the two debtors teach about the weeping woman?", choices:["That she was seeking attention","That much forgiveness awakens much love","That only hosts should serve guests","That Simon owed her an apology"], a:1, why:"To whom little is forgiven, the same loveth little; her many sins were forgiven, for she loved much." }
    ] },
  { n:8, summary:"Jesus preaches the kingdom through every city and village, with the twelve and certain women — Mary called Magdalene, Joanna the wife of Chuza, and Susanna — ministering to him of their substance. To a great crowd he gives the parable of the sower: the seed is the word of God, and the soils are hearts, from the wayside where the devil takes the word to the honest and good heart that keeps it and brings forth fruit with patience. His family, he answers, are those who hear the word of God and do it. Crossing the lake he sleeps through a storm that nearly sinks the ship; rebuked, wind and water cease, and he asks, Where is your faith? In the Gadarenes a legion of devils is driven from a wild man, who is sent home to publish what God has done. Jairus's dying daughter is raised after a woman with a twelve-year issue of blood touches his garment's border and is healed; to the father he had said, Fear not: believe only.",
    context:"Across Galilee and the lake, Jesus teaches parables, stills a storm, frees a legion-possessed man, and raises Jairus's daughter.",
    keyVerses:[
      { ref:"Luke 8:15", text:"But that on the good ground are they, which in an honest and good heart, having heard the word, keep it, and bring forth fruit with patience." },
      { ref:"Luke 8:21", text:"And he answered and said unto them, My mother and my brethren are these which hear the word of God, and do it." },
      { ref:"Luke 8:50", text:"But when Jesus heard it, he answered him, saying, Fear not: believe only, and she shall be made whole." }
    ],
    takeaway:"Keep the word in an honest heart; believing fearlessness meets both storm and death.",
    quiz:[
      { q:"Which women are named as ministering to Jesus of their substance?", choices:["Martha, Mary, and Salome","Anna, Elisabeth, and Dorcas","Priscilla, Lydia, and Phoebe","Mary called Magdalene, Joanna the wife of Chuza, and Susanna"], a:3, why:"Luke names Mary called Magdalene, Joanna the wife of Chuza Herod's steward, and Susanna, and many others." },
      { q:"In the parable's explanation, what sets the good ground apart?", choices:["The deepest soil in the field","An honest and good heart that keeps the word and brings forth fruit with patience","Daily watering by the disciples","Absence of birds"], a:1, why:"The good ground hearers, in an honest and good heart, keep the word and bring forth fruit with patience." },
      { q:"What had Jesus said to Jairus before raising his daughter?", choices:["To hire mourners for the house","That it was too late to come","To sell all he had","Fear not: believe only, and she shall be made whole"], a:2, why:"When word came that the girl was dead, Jesus answered Jairus, Fear not: believe only, and she shall be made whole." }
    ] },
  { n:9, summary:"Jesus sends the twelve to preach the kingdom and heal, with neither staves, scrip, bread, nor money; Herod, having beheaded John, desires to see him. After the apostles return, five thousand are fed from five loaves and two fishes, with twelve baskets of fragments left. Alone in prayer with his disciples, he asks whom people say he is; Peter answers, The Christ of God, and Jesus teaches that the Son of man must suffer, be slain, and rise the third day, and that his follower must deny himself and take up his cross daily. On a mountain Peter, John, and James see him transfigured, speaking with Moses and Elias of his decease, while a voice says, This is my beloved Son: hear him. Below, he casts a devil from a father's only son, foretells his betrayal again, and answers a greatness dispute with a child: he that is least among you all, the same shall be great. Rejected by a Samaritan village, he refuses James and John's call for fire and steadfastly sets his face toward Jerusalem.",
    context:"Across Galilee and toward Jerusalem, Jesus sends out the Twelve, feeds five thousand, is transfigured, and begins the journey south.",
    keyVerses:[
      { ref:"Luke 9:23", text:"And he said to them all, If any man will come after me, let him deny himself, and take up his cross daily, and follow me." },
      { ref:"Luke 9:35", text:"And there came a voice out of the cloud, saying, This is my beloved Son: hear him." },
      { ref:"Luke 9:56", text:"For the Son of man is not come to destroy men's lives, but to save them." }
    ],
    takeaway:"Discipleship is daily self-denial under the beloved Son, who came to save, not destroy.",
    quiz:[
      { q:"How much food fed the five thousand in this chapter?", choices:["Seven loaves and a few fishes","Five loaves and two fishes","Two loaves and a young cow","One loaf borrowed from a lad"], a:1, why:"The disciples had no more but five loaves and two fishes, yet all did eat and were filled." },
      { q:"What was Peter's answer when Jesus asked, But whom say ye that I am?", choices:["Elias returned to earth","The Christ of God","A teacher sent by Herod","One of the old prophets risen again"], a:1, why:"Peter answered and said, The Christ of God." },
      { q:"What did Jesus answer the dispute over who should be greatest?", choices:["That Peter was chief among them","That greatness was decided by age","That he that is least among you all, the same shall be great","That greatness belongs to miracle workers"], a:2, why:"Setting a child by him, he taught that he that is least among you all, the same shall be great." }
    ] },
  { n:10, summary:"Jesus appoints seventy others and sends them two by two ahead of him, as lambs among wolves, to heal the sick and announce that the kingdom of God is come nigh. They return joyful that devils are subject to them; he redirects their joy — rejoice rather that their names are written in heaven — and rejoices in spirit that the Father has revealed these things to babes. Asked by a lawyer what he shall do to inherit eternal life, Jesus draws out the great commandments; pressed to define his neighbor, he tells of a wounded traveler passed by a priest and a Levite but befriended at cost by a despised Samaritan, who binds his wounds, carries him to an inn, and pays his keep. Go, and do thou likewise. In a village, Martha, cumbered about much serving, asks Jesus to make her sister Mary help; he answers that Mary has chosen the good part — sitting at his feet to hear his word — which shall not be taken away.",
    context:"On the journey to Jerusalem, Jesus sends out the seventy, teaches a lawyer with the parable of the good Samaritan, and visits Martha and Mary.",
    keyVerses:[
      { ref:"Luke 10:2", text:"Therefore said he unto them, The harvest truly is great, but the labourers are few: pray ye therefore the Lord of the harvest, that he would send forth labourers into his harvest." },
      { ref:"Luke 10:37", text:"And he said, He that shewed mercy on him. Then said Jesus unto him, Go, and do thou likewise." },
      { ref:"Luke 10:42", text:"But one thing is needful: and Mary hath chosen that good part, which shall not be taken away from her." }
    ],
    takeaway:"The true neighbor shows mercy at cost, and hearing Christ himself is the good part chosen by Mary.",
    quiz:[
      { q:"How many did Jesus appoint and send out two by two in this chapter?", choices:["Twelve","Forty","Seventy","Five hundred"], a:1, why:"The Lord appointed other seventy also, and sent them two and two before his face." },
      { q:"Which two men passed by the wounded traveler in the parable?", choices:["A farmer and a merchant","A soldier and a tax collector","A scribe and a Pharisee","A priest and a Levite"], a:2, why:"A priest, and likewise a Levite, saw the wounded man and passed by on the other side." },
      { q:"What did Jesus say should be the source of the seventy's joy?", choices:["That devils were subject unto them","That they lacked nothing on the journey","That cities feared their arrival","That their names are written in heaven"], a:3, why:"He told them to rejoice not that spirits were subject, but rather because their names are written in heaven." }
    ] },
  { n:11, summary:"Watching Jesus pray, a disciple asks, Lord, teach us to pray. The answer gives the pattern of the Lord's prayer — hallowed name, coming kingdom, daily bread, forgiveness, deliverance from evil — followed by the friend at midnight, whose importunity obtains loaves for a traveler. Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you: if faulty earthly fathers give good gifts, how much more shall the heavenly Father give the Holy Spirit to them that ask him. Accused of casting out devils through Beelzebub, Jesus answers that a kingdom divided against itself falls, and that if he casts out devils with the finger of God, no doubt the kingdom of God is come upon you. An evil generation seeking a sign gets only the sign of Jonas, for a greater than Jonas and than Solomon is here. At a Pharisee's table he pronounces woes on those who tithe herbs while passing over judgment and the love of God, love chief seats, and take away the key of knowledge.",
    context:"In Galilee, Jesus teaches the Lord's prayer, answers charges of casting out devils through Beelzebub, and pronounces woes at a Pharisee's table.",
    keyVerses:[
      { ref:"Luke 11:9", text:"And I say unto you, Ask, and it shall be given you; seek, and ye shall find; knock, and it shall be opened unto you." },
      { ref:"Luke 11:13", text:"If ye then, being evil, know how to give good gifts unto your children: how much more shall your heavenly Father give the Holy Spirit to them that ask him?" },
      { ref:"Luke 11:28", text:"But he said, Yea rather, blessed are they that hear the word of God, and keep it." }
    ],
    takeaway:"Persistent prayer reaches a giving Father, and blessing rests on hearing and keeping the word of God.",
    quiz:[
      { q:"What did the friend at midnight finally provide?", choices:["Nothing at all","Money for the journey","As many loaves as his neighbor needed","Oil for a lamp"], a:2, why:"Because of his friend's importunity he rose and gave him as many as he needed." },
      { q:"What sign did Jesus say an evil generation seeking a sign would receive?", choices:["Signs in the sun and moon","The temple's rebuilding","Fire from heaven","The sign of Jonas the prophet"], a:3, why:"As Jonas was a sign unto the Ninevites, so shall the Son of man be to that generation." },
      { q:"Whom did Jesus declare blessed over the woman who praised his mother?", choices:["Those who tithe mint and rue","Those who wash before dinner","Those who build prophets' tombs","They that hear the word of God, and keep it"], a:0, why:"He answered, Yea rather, blessed are they that hear the word of God, and keep it." }
    ] },
  { n:12, summary:"Before a great multitude Jesus warns against the leaven of the Pharisees, hypocrisy, for nothing covered shall not be revealed. Disciples need not fear those who can kill only the body; the God who numbers sparrows and the very hairs of the head is to be feared. When a man asks him to divide an inheritance, Jesus tells of the rich fool, whose larger barns cannot keep a soul required of God that night: life consisteth not in the abundance of possessions. To his disciples he points to the ravens and the lilies: seek not what ye shall eat, but seek the kingdom of God, and lay up treasure in heaven, where the heart follows. Servants must watch, for the lord may come at any watch; the steward found doing is blessed, but the one who says my lord delayeth his coming is cut off — unto whomsoever much is given, of him shall be much required. Jesus has come to send fire, dividing even households, and he marvels that people read the sky but cannot discern this time.",
    context:"Teaching an enormous crowd and his disciples on the way to Jerusalem, Jesus warns against hypocrisy, covetousness, and spiritual unpreparedness.",
    keyVerses:[
      { ref:"Luke 12:15", text:"And he said unto them, Take heed, and beware of covetousness: for a man's life consisteth not in the abundance of the things which he possesseth." },
      { ref:"Luke 12:31", text:"But rather seek ye the kingdom of God; and all these things shall be added unto you." },
      { ref:"Luke 12:34", text:"For where your treasure is, there will your heart be also." }
    ],
    takeaway:"Seek the kingdom first; God knows your needs, and hearts follow the treasure we choose.",
    quiz:[
      { q:"In the parable, what did the rich fool plan to build?", choices:["A new vineyard wall","A granary for the poor","A tower reaching heaven","Greater barns for his fruits and goods"], a:3, why:"The rich man said, I will pull down my barns, and build greater, to bestow all his fruits and goods." },
      { q:"What argument does Jesus draw from the ravens and the lilies?", choices:["That work is unnecessary","That God feeds and clothes what he values, so disciples need not be anxious","That beauty matters more than food","That Solomon was a poor steward"], a:0, why:"God feeds the ravens and clothes the lilies better than Solomon in all his glory; disciples of little faith need not take anxious thought." },
      { q:"What rule does Jesus give about accountability?", choices:["The less given, the more required","Only leaders are accountable","Ignorance erases responsibility","Unto whomsoever much is given, of him shall be much required"], a:1, why:"Unto whomsoever much is given, of him shall be much required; to whom men have committed much, they ask the more." }
    ] },
  { n:13, summary:"Told of Galilaeans whose blood Pilate mingled with their sacrifices, Jesus denies they were worse sinners: except ye repent, ye shall all likewise perish — the same lesson drawn from eighteen killed when the tower in Siloam fell. A fig tree given one more year of digging and dunging pictures both a deadline and patience. In a synagogue on the sabbath he looses a woman bowed together eighteen years; to an indignant ruler he answers that each of them looses an ox on the sabbath, and ought not this daughter of Abraham be loosed? Adversaries are ashamed, and the people rejoice. The kingdom is like a mustard seed grown into a great tree and like leaven hidden in three measures of meal. Asked whether few are saved, he urges striving at the strait gate and says some from east, west, north, and south will sit down in the kingdom, where the last are first. Warned that Herod will kill him, he laments over Jerusalem like a hen longing to gather her brood, whom they would not receive.",
    context:"Teaching on the journey toward Jerusalem, Jesus calls all to repentance, heals a bowed woman on the sabbath, and mourns over Jerusalem.",
    keyVerses:[
      { ref:"Luke 13:3", text:"I tell you, Nay: but, except ye repent, ye shall all likewise perish." },
      { ref:"Luke 13:30", text:"And, behold, there are last which shall be first, and there are first which shall be last." },
      { ref:"Luke 13:34", text:"O Jerusalem, Jerusalem, which killest the prophets, and stonest them that are sent unto thee; how often would I have gathered thy children together, as a hen doth gather her brood under her wings, and ye would not!" }
    ],
    takeaway:"Repentance has a season; the Lord longs to gather his people, and the strait gate will not always stand open.",
    quiz:[
      { q:"How long had the woman in the synagogue been bowed together?", choices:["Eighteen years","Seven years","Three years","Forty years"], a:0, why:"She had a spirit of infirmity eighteen years and could in no wise lift up herself." },
      { q:"What two small things picture the kingdom of God here?", choices:["A stone and a river","Bread and wine","A mustard seed and leaven hidden in meal","Salt and a lamp"], a:2, why:"The kingdom is like a grain of mustard seed grown into a great tree and like leaven hid in three measures of meal." },
      { q:"What image did Jesus use when he mourned over Jerusalem?", choices:["A lion over its den","A shepherd over a scattered flock","A watchman over a dark city","A hen gathering her brood under her wings"], a:3, why:"He would have gathered her children as a hen doth gather her brood under her wings, and ye would not." }
    ] },
  { n:14, summary:"At a sabbath meal in a chief Pharisee's house, Jesus heals a man with the dropsy after asking whether it is lawful to heal on the sabbath day. Watching guests choose the chief rooms, he teaches the wedding-guest parable: take the lowest room, for whosoever exalteth himself shall be abased, and he that humbleth himself shall be exalted. To the host he says to invite the poor, the maimed, the lame, and the blind, who cannot recompense — their recompense comes at the resurrection of the just. When a guest blesses those who shall eat bread in the kingdom of God, Jesus answers with the great supper: the invited all make excuse — bought ground, five yoke of oxen, a new wife — so the master fills his house from the streets and the highways and hedges, and none of the first-bidden shall taste of his supper. To the multitudes following he sets the cost of discipleship: bearing the cross, counting the cost, and forsaking all that he hath.",
    context:"At a sabbath meal in the house of a chief Pharisee, Jesus teaches humility, hospitality to the poor, and the cost of discipleship.",
    keyVerses:[
      { ref:"Luke 14:11", text:"For whosoever exalteth himself shall be abased; and he that humbleth himself shall be exalted." },
      { ref:"Luke 14:13", text:"But when thou makest a feast, call the poor, the maimed, the lame, the blind:" },
      { ref:"Luke 14:27", text:"And whosoever doth not bear his cross, and come after me, cannot be my disciple." }
    ],
    takeaway:"Humility is exalted, feasts for those who cannot repay are richest, and discipleship must be counted before it is begun.",
    quiz:[
      { q:"What ailment did the man at the Pharisee's table have?", choices:["Blindness","The dropsy","A fever","A withered hand"], a:1, why:"Before Jesus stood a certain man which had the dropsy, and he healed him on the sabbath." },
      { q:"What excuses did the invited guests give for missing the great supper?", choices:["Sickness, storms, and debts","Fear of the king, taxes, and weather","No invitation had been sent them","Bought ground, five yoke of oxen, and a new wife"], a:3, why:"They all with one consent began to make excuse: land to see, oxen to prove, and a wife just married." },
      { q:"What point does the tower-builder parable make?", choices:["Construction is a poor investment","Kings should always seek peace first","Honest excuses are acceptable","Discipleship demands counting the cost before committing"], a:0, why:"A builder counts whether he can finish, so likewise whosoever forsaketh not all that he hath cannot be Christ's disciple." }
    ] },
  { n:15, summary:"When publicans and sinners draw near and Pharisees murmur that he receives them, Jesus answers with three parables. A shepherd leaves the ninety-nine to find the lost sheep and carries it home rejoicing — so there is joy in heaven over one sinner that repenteth. A woman with ten pieces of silver sweeps and searches until she finds the lost coin, and there is joy in the presence of the angels of God over one sinner that repenteth. A younger son demands his inheritance, wastes it in a far country, and ends feeding swine and longing for their husks. Coming to himself, he resolves to return and confess, Father, I have sinned against heaven, and before thee. While he is yet a great way off, his father sees him, runs, embraces him, and restores him with robe, ring, and fatted calf: this my son was dead, and is alive again. The elder brother's anger is answered: all the father has is his, yet it was right to make merry, for this thy brother was lost, and is found.",
    context:"Answering Pharisees and scribes who murmured that he received sinners, Jesus tells three parables of things lost and found.",
    keyVerses:[
      { ref:"Luke 15:7", text:"I say unto you, that likewise joy shall be in heaven over one sinner that repenteth, more than over ninety and nine just persons, which need no repentance." },
      { ref:"Luke 15:20", text:"And he arose, and came to his father. But when he was yet a great way off, his father saw him, and had compassion, and ran, and fell on his neck, and kissed him." },
      { ref:"Luke 15:32", text:"It was meet that we should make merry, and be glad: for this thy brother was dead, and is alive again; and was lost, and is found." }
    ],
    takeaway:"Heaven rejoices over every sinner who repents; the Father runs to meet the returning.",
    quiz:[
      { q:"What job did the prodigal take in the far country?", choices:["Tending vineyards","Fishing","Feeding swine","Building barns"], a:2, why:"He joined himself to a citizen of that country, who sent him into his fields to feed swine." },
      { q:"How many pieces of silver did the woman lose in the parable?", choices:["One of ten","One of a hundred","Two of seven","Five of fifty"], a:0, why:"The woman with ten pieces of silver lost one and searched the house until she found it." },
      { q:"What does the father's answer to the elder brother teach?", choices:["That inheritance laws were unfair","That celebrating the lost who return is right — this thy brother was dead, and is alive again","That the younger son should be punished","That servants matter more than sons"], a:1, why:"It was meet to make merry, for this thy brother was dead, and is alive again; and was lost, and is found." }
    ] },
  { n:16, summary:"Jesus tells his disciples of an unjust steward about to be dismissed who shrewdly reduces his lord's debtors' bills; his lord commends not the dishonesty but the wisdom, for the children of this world are in their generation wiser than the children of light. The lesson follows: he that is faithful in that which is least is faithful also in much, true riches belong to those trustworthy with another man's goods, and no servant can serve two masters — ye cannot serve God and mammon. Covetous Pharisees deride him, and he answers that what is highly esteemed among men is abomination in the sight of God. Then comes the account of the rich man clothed in purple and Lazarus, the beggar full of sores at his gate. Both die: Lazarus is carried by angels into Abraham's bosom; the rich man, tormented in hell, begs a drop of water and then a warning sent to his five brothers. Abraham answers that they have Moses and the prophets, and neither will a messenger from the dead persuade those who refuse them.",
    context:"Speaking to his disciples and to covetous Pharisees, Jesus teaches stewardship and tells the account of the rich man and Lazarus.",
    keyVerses:[
      { ref:"Luke 16:10", text:"He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much." },
      { ref:"Luke 16:13", text:"No servant can serve two masters: for either he will hate the one, and love the other; or else he will hold to the one, and despise the other. Ye cannot serve God and mammon." },
      { ref:"Luke 16:31", text:"And he said unto him, If they hear not Moses and the prophets, neither will they be persuaded, though one rose from the dead." }
    ],
    takeaway:"Faithful in least, faithful in much: no one can serve God and mammon together.",
    quiz:[
      { q:"Who was carried by angels into Abraham's bosom?", choices:["The unjust steward","The rich man's servants","The rich man","Lazarus the beggar"], a:3, why:"The beggar died and was carried by the angels into Abraham's bosom." },
      { q:"What did the unjust steward do that won his lord's backhanded commendation?", choices:["Paid every debt in full","Acted shrewdly to provide for himself before being put out of the stewardship","Ran away to a far country","Confessed his theft publicly"], a:1, why:"By lowering the debtors' bills he made friends for his future, and the lord commended that he had done wisely." },
      { q:"What did Abraham say could persuade the rich man's five brothers?", choices:["A messenger returned from the dead","Another famine like past ones","A written account of torment","Nothing beyond Moses and the prophets — if they will not hear them, no miracle will persuade them"], a:2, why:"They have Moses and the prophets; if they hear not them, neither will they be persuaded though one rose from the dead." }
    ] },
  { n:17, summary:"Jesus warns that offences will surely come, but woe to him through whom they come: better a millstone about his neck than to offend one of these little ones. Forgiveness is repeated — if a brother trespass and repent seven times in a day, forgive him. The apostles' plea, Increase our faith, is answered: faith as a grain of mustard seed could command a sycamine tree into the sea, and servants who have done all commanded should say, We are unprofitable servants. Passing through Samaria toward Jerusalem, Jesus cleanses ten lepers who cry for mercy, sending them to the priests; as they go they are cleansed, but only one — a Samaritan — turns back to glorify God and give thanks, and he alone hears, thy faith hath made thee whole. Asked by Pharisees when the kingdom of God should come, he answers that it cometh not with observation: the kingdom of God is within you. The days of the Son of man will come as suddenly as the days of Noe and of Lot.",
    context:"On the road through Samaria toward Jerusalem, Jesus teaches forgiveness, faith, and gratitude, and warns of his sudden coming.",
    keyVerses:[
      { ref:"Luke 17:6", text:"And the Lord said, If ye had faith as a grain of mustard seed, ye might say unto this sycamine tree, Be thou plucked up by the root, and be thou planted in the sea; and it should obey you." },
      { ref:"Luke 17:19", text:"And he said unto him, Arise, go thy way: thy faith hath made thee whole." },
      { ref:"Luke 17:21", text:"Neither shall they say, Lo here! or, lo there! for, behold, the kingdom of God is within you." }
    ],
    takeaway:"Even small faith acts; gratitude completes healing; and clinging to this life loses what matters most.",
    quiz:[
      { q:"How many of the ten lepers returned to give thanks?", choices:["All ten","Nine","One","None"], a:0, why:"One of them, when he saw that he was healed, turned back, glorifying God." },
      { q:"What was the nationality of the grateful leper?", choices:["He was a Samaritan","He was a priest","He was from Bethany","He was a Roman soldier"], a:1, why:"He fell at Jesus' feet giving thanks, and he was a Samaritan, a stranger whom Jesus called back to wholeness." },
      { q:"What does the mustard-seed answer to Increase our faith teach?", choices:["That faith requires grand beginnings","That even small faith, exercised, can do what seems impossible","That faith belongs only to apostles","That obstacles can never be moved"], a:2, why:"Faith as a grain of mustard seed could command a sycamine tree to be plucked up and planted in the sea." }
    ] },
  { n:18, summary:"Jesus teaches that men ought always to pray and not to faint, telling of a widow who wears down a judge who fears neither God nor man. A second parable contrasts a Pharisee proud of fasting and tithing with a publican who will not lift his eyes to heaven but cries, God be merciful to me a sinner. The publican, not the Pharisee, goes home justified, for he that humbleth himself shall be exalted. When infants are brought and the disciples rebuke the bringers, Jesus calls the children, for of such is the kingdom of God. A rich ruler goes away sorrowful at the call to sell all and follow; Jesus notes how hardly the rich enter the kingdom, yet the things which are impossible with men are possible with God, and those who leave all receive manifold more and life everlasting. Nearing Jerusalem he foretells his death and resurrection — which the twelve do not understand — then gives sight to a blind beggar crying to the Son of David.",
    context:"Teaching on the way up to Jerusalem, Jesus speaks on prayer and humility, welcomes children, and meets the rich ruler near Jericho.",
    keyVerses:[
      { ref:"Luke 18:13", text:"And the publican, standing afar off, would not lift up so much as his eyes unto heaven, but smote upon his breast, saying, God be merciful to me a sinner." },
      { ref:"Luke 18:16", text:"But Jesus called them unto him, and said, Suffer little children to come unto me, and forbid them not: for of such is the kingdom of God." },
      { ref:"Luke 18:27", text:"And he said, The things which are impossible with men are possible with God." }
    ],
    takeaway:"Heaven hears the humble: persistent prayer and a contrite heart outweigh self-impressed righteousness.",
    quiz:[
      { q:"In the second parable, how did the publican pray?", choices:["Loudly from the front row","With a list of his tithes","Standing afar off, unwilling to lift even his eyes to heaven","By reciting the law from memory"], a:1, why:"He stood afar off, would not lift up his eyes to heaven, smote upon his breast, and begged mercy." },
      { q:"What did the unjust judge finally decide, and why?", choices:["To exile the widow for her shouting","To avenge her, because her continual coming wearied him","To bribe her adversaries to keep peace","To send the case to the elders"], a:2, why:"He yielded to the widow's continual coming, and Jesus argued that God will much more avenge his own elect." },
      { q:"What comfort does Jesus give after the rich ruler leaves sorrowful?", choices:["That wealth is a mark of favor","That the ruler was never sincere","That only the apostles must sacrifice","That the things which are impossible with men are possible with God"], a:3, why:"When the hearers asked who then can be saved, Jesus said the impossible with men is possible with God." }
    ] },
  { n:19, summary:"At Jericho the chief publican Zacchaeus, little of stature, climbs a sycomore tree to see Jesus, who calls him down to lodge at his house. Murmuring crowds hear Zacchaeus vow to give half his goods to the poor and restore fourfold anything taken by false accusation; Jesus declares, This day is salvation come to this house, for the Son of man is come to seek and to save that which was lost. Because the people expect the kingdom to appear at once, he tells of a nobleman who travels to receive a kingdom, leaves his servants money to occupy till he comes, and on return rewards the faithful with authority over cities while his enemies are slain. Riding a colt down the mount of Olives amid disciples crying, Blessed be the King that cometh in the name of the Lord, he answers Pharisees that the stones would immediately cry out. He weeps over the city, prophesying siege because it knew not the time of its visitation, then casts the sellers from the temple and teaches daily.",
    context:"At Jericho and on the descent from the mount of Olives into Jerusalem, Jesus seeks the lost, weeps over the city, and cleanses the temple.",
    keyVerses:[
      { ref:"Luke 19:10", text:"For the Son of man is come to seek and to save that which was lost." },
      { ref:"Luke 19:41", text:"And when he was come near, he beheld the city, and wept over it," },
      { ref:"Luke 19:46", text:"Saying unto them, It is written, My house is the house of prayer: but ye have made it a den of thieves." }
    ],
    takeaway:"Christ comes seeking and saving the lost — and weeping over those who miss their day of visitation.",
    quiz:[
      { q:"Why did Zacchaeus climb into a sycomore tree?", choices:["To hide from the crowds","To throw fruit to Jesus","Because he was little of stature and could not see for the press","To escape the temple guards"], a:2, why:"He sought to see Jesus but could not for the press, because he was little of stature." },
      { q:"What reward did the servant who gained ten pounds receive?", choices:["A palace in Jerusalem","Freedom from all taxes","A seat at the nobleman's table","Authority over ten cities"], a:3, why:"Because thou hast been faithful in a very little, the nobleman gave him authority over ten cities." },
      { q:"How did Jesus respond when Pharisees told him to rebuke his disciples?", choices:["He silenced the crowd himself","He rebuked the Pharisees sharply","He wept at once","He said that if these should hold their peace, the stones would immediately cry out"], a:0, why:"He answered that if these should hold their peace, the stones would immediately cry out." }
    ] },
  { n:20, summary:"While Jesus teaches in the temple, chief priests, scribes, and elders demand to know by what authority he acts; his counter-question about John's baptism — from heaven or of men — leaves them stonewalled. The parable of the vineyard follows: servants sent for fruit are beaten, and the beloved son, sent last, is cast out and killed. Quoting the stone the builders rejected, he warns that on whomsoever it falls it will grind him to powder, and the leaders, seeing it is against them, fear to seize him. Spies flatter him and ask about tribute to Caesar; holding the penny, he answers, Render therefore unto Caesar the things which be Caesar's, and unto God the things which be God's. Sadducees who deny resurrection pose the seven-brothers riddle; Jesus answers that the worthy of that world neither marry nor die, being children of the resurrection, and that God is not a God of the dead, but of the living, for all live unto him. He then asks how David calls the Christ Lord and warns against scribes who devour widows' houses.",
    context:"During his last days teaching in the Jerusalem temple, Jesus parries challenges from chief priests, scribes, spies, and Sadducees.",
    keyVerses:[
      { ref:"Luke 20:17", text:"And he beheld them, and said, What is this then that is written, The stone which the builders rejected, the same is become the head of the corner?" },
      { ref:"Luke 20:25", text:"And he said unto them, Render therefore unto Cæsar the things which be Cæsar's, and unto God the things which be God's." },
      { ref:"Luke 20:38", text:"For he is not a God of the dead, but of the living: for all live unto him." }
    ],
    takeaway:"Give God what bears his image — your whole self — and trust him in whom all live.",
    quiz:[
      { q:"What question did the temple leaders refuse to answer?", choices:["Whether they kept the law of Moses","Whether Caesar ruled justly","Whether angels had bodies","Whether the baptism of John was from heaven or of men"], a:3, why:"Asked whether John's baptism was from heaven or of men, they said they could not tell, and Jesus declined to answer." },
      { q:"What did the husbandmen do to the beloved son in the vineyard parable?", choices:["Sent him away hungry","Cast him out of the vineyard and killed him","Made him the vineyard's ruler","Ignored him entirely"], a:0, why:"They reasoned, This is the heir: come, let us kill him, that the inheritance may be ours; so they cast him out and killed him." },
      { q:"How did Jesus answer the Sadducees' marriage riddle?", choices:["That marriage continues after death","That they were right to wonder","That Moses never wrote such laws","That the worthy of that world neither marry nor die, being children of the resurrection"], a:1, why:"The children of the resurrection neither marry nor die, and God is the God of the living, for all live unto him." }
    ] },
  { n:21, summary:"Watching the treasury, Jesus sees a poor widow cast in two mites and says she has given more than they all — of her penury, all the living she had. Told of the temple's goodly stones, he answers that the days will come when not one stone is left upon another. On the mount of Olives he gives signs: take heed of deceivers; wars, earthquakes, famines, and pestilences are not yet the end. Before those things, disciples will be delivered up for his name's sake — it shall turn to them for a testimony, for he will give them a mouth and wisdom no adversary can resist; in patience they possess their souls. Jerusalem compassed with armies means desolation is nigh, until the times of the Gentiles be fulfilled. Then signs in sun, moon, and stars precede the Son of man coming in a cloud with power and great glory — look up, for redemption draweth nigh. Watch ye therefore, and pray always, that ye may stand before the Son of man.",
    context:"From the temple treasury to the mount of Olives in his final week, Jesus contrasts true and false riches and foretells Jerusalem's fall.",
    keyVerses:[
      { ref:"Luke 21:4", text:"For all these have of their abundance cast in unto the offerings of God: but she of her penury hath cast in all the living that she had." },
      { ref:"Luke 21:28", text:"And when these things begin to come to pass, then look up, and lift up your heads; for your redemption draweth nigh." },
      { ref:"Luke 21:36", text:"Watch ye therefore, and pray always, that ye may be accounted worthy to escape all these things that shall come to pass, and to stand before the Son of man." }
    ],
    takeaway:"In a world of signs and distress, believers watch, pray, and lift their heads, for redemption draws nigh.",
    quiz:[
      { q:"What did the poor widow cast into the treasury?", choices:["Two mites","A bag of gold","Ten talents","A silver coin of Caesar"], a:0, why:"He saw a certain poor widow casting in thither two mites, and said she had cast in more than they all." },
      { q:"What sign did Jesus give that Jerusalem's desolation is nigh?", choices:["A three-year famine","The temple gold being melted","Seeing Jerusalem compassed with armies","Roman coins in the temple court"], a:2, why:"When ye shall see Jerusalem compassed with armies, then know that the desolation thereof is nigh." },
      { q:"What attitude did Jesus command when these things begin to come to pass?", choices:["To hide in the mountains forever","To calculate the exact hour","To abandon the city's believers","To look up and lift up your heads, for your redemption draweth nigh"], a:3, why:"These signs mark not despair but hope: look up, and lift up your heads, for your redemption draweth nigh." }
    ] },
  { n:22, summary:"As passover nears, Satan enters Judas, who bargains with the chief priests; Peter and John prepare the feast in a large upper room. At the table Jesus gives the cup and the bread — this do in remembrance of me — and answers the strife over greatness by pointing to his own place as he that serveth. He warns Simon that Satan desires to sift him as wheat: I have prayed for thee, that thy faith fail not — yet the cock will not crow before Peter denies him thrice. On the mount of Olives he prays that the cup might pass — nevertheless not my will, but thine, be done; an angel strengthens him, and in agony his sweat is as great drops of blood. Judas betrays him with a kiss, and Jesus heals the ear a disciple cut off — this is your hour, and the power of darkness. In the high priest's hall Peter denies him three times; when the cock crows, the Lord turns and looks upon Peter, and he goes out and weeps bitterly.",
    context:"In Jerusalem at passover, Jesus institutes the sacrament, agonizes on the mount of Olives, and is betrayed, denied, and brought before the council.",
    keyVerses:[
      { ref:"Luke 22:19", text:"And he took bread, and gave thanks, and brake it, and gave unto them, saying, This is my body which is given for you: this do in remembrance of me." },
      { ref:"Luke 22:32", text:"But I have prayed for thee, that thy faith fail not: and when thou art converted, strengthen thy brethren." },
      { ref:"Luke 22:42", text:"Saying, Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done." }
    ],
    takeaway:"Remember the body and blood given for you; Gethsemane teaches the prayer that yields all.",
    quiz:[
      { q:"What did Jesus ask the Father in Gethsemane?", choices:["That his disciples be spared suffering","If thou be willing, remove this cup from me: nevertheless not my will, but thine, be done","That the multitude disperse at once","That Judas be struck blind"], a:1, why:"He knelt and prayed that the cup might be removed if the Father willed, yet yielded: not my will, but thine, be done." },
      { q:"What unusual details does Luke record of Jesus's agony?", choices:["He was silent the whole night","Fire descended on the garden","The disciples sang until dawn","An angel strengthened him, and his sweat was as it were great drops of blood"], a:3, why:"An angel appeared from heaven strengthening him, and being in an agony he prayed more earnestly, his sweat as great drops of blood." },
      { q:"What did Peter do when the Lord turned and looked upon him?", choices:["He denied him a fourth time","He drew a sword again","He went out and wept bitterly","He fled immediately to Galilee"], a:0, why:"Peter remembered the Lord's word, went out, and wept bitterly." }
    ] },
  { n:23, summary:"The council leads Jesus to Pilate, accusing him of perverting the nation; Pilate finds no fault, and on hearing Galilee mentioned sends him to Herod, who hopes for a miracle but receives only silence. Mocked with a gorgeous robe and sent back, Jesus returns to Pilate, and Herod and Pilate are made friends that day. Pilate offers chastisement and release, but the crowd demands Barabbas, imprisoned for sedition and murder, crying, Crucify him, crucify him — and Pilate gives sentence as they require. Simon of Cyrene carries the cross, and Jesus tells the weeping women to weep rather for themselves and their children. At Calvary, between two malefactors, he prays, Father, forgive them; for they know not what they do. One malefactor rails; the other confesses Jesus's innocence and asks to be remembered in his kingdom, and receives, To day shalt thou be with me in paradise. Darkness covers the earth, the veil of the temple is rent, and Jesus commends his spirit and dies. Joseph of Arimathaea begs the body and lays it in a hewn tomb.",
    context:"Condemned before Pilate and Herod at Jerusalem, Jesus is crucified at Calvary between two malefactors and buried before the sabbath.",
    keyVerses:[
      { ref:"Luke 23:34", text:"Then said Jesus, Father, forgive them; for they know not what they do. And they parted his raiment, and cast lots." },
      { ref:"Luke 23:43", text:"And Jesus said unto him, Verily I say unto thee, To day shalt thou be with me in paradise." },
      { ref:"Luke 23:46", text:"And when Jesus had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost." }
    ],
    takeaway:"Even dying, Christ forgives and saves: he commends his spirit to the Father and opens paradise to the penitent.",
    quiz:[
      { q:"To which ruler did Pilate send Jesus after hearing he was of Galilee?", choices:["Caiaphas","Annas","Herod","Felix"], a:2, why:"Hearing that Jesus belonged to Herod's jurisdiction, Pilate sent him to Herod, who was at Jerusalem that day." },
      { q:"What did Jesus tell the women who bewailed him on the way to Calvary?", choices:["Nothing at all","Weep not for me, but weep for yourselves, and for your children","To follow at a distance","To carry word to Peter"], a:0, why:"Turning to them he said, Daughters of Jerusalem, weep not for me, but weep for yourselves, and for your children." },
      { q:"What did the penitent malefactor recognize that the first did not?", choices:["That the crowd wanted him freed","That they were punished justly, but this man had done nothing amiss","That a rescue was coming","That Pilate was merciful"], a:1, why:"He rebuked the railing thief: they received the due reward of their deeds, but this man hath done nothing amiss." }
    ] },
  { n:24, summary:"Very early on the first day of the week, women come with spices and find the stone rolled away and the body of the Lord Jesus gone. Two men in shining garments ask why they seek the living among the dead — he is not here, but is risen. The apostles treat the report as idle tales, though Peter runs to see the linen clothes lying alone. Two walking to Emmaus are joined by Jesus, unrecognized as he explains from Moses and the prophets why Christ ought to suffer and enter into his glory; they know him in the breaking of bread and hurry back to Jerusalem. As they speak, Jesus stands among them, Peace be unto you. He shows his hands and feet — a spirit hath not flesh and bones — eats fish before them, and sends them to preach repentance and remission of sins among all nations, beginning at Jerusalem, as witnesses who must tarry for power from on high. From Bethany he is carried up into heaven, and they return with great joy.",
    context:"From the empty tomb to Emmaus, an upper room, and Bethany, Luke closes with the risen Christ appearing, teaching, and ascending.",
    keyVerses:[
      { ref:"Luke 24:6", text:"He is not here, but is risen: remember how he spake unto you when he was yet in Galilee," },
      { ref:"Luke 24:39", text:"Behold my hands and my feet, that it is I myself: handle me, and see; for a spirit hath not flesh and bones, as ye see me have." },
      { ref:"Luke 24:47", text:"And that repentance and remission of sins should be preached in his name among all nations, beginning at Jerusalem." }
    ],
    takeaway:"The risen Lord opens the scriptures and our understanding, sends witnesses, and ascends — leaving joy behind.",
    quiz:[
      { q:"What did the risen Jesus eat before the assembled disciples?", choices:["Bread and wine only","Lamb and bitter herbs","Figs and dates","A piece of a broiled fish, and of an honeycomb"], a:3, why:"They gave him a piece of a broiled fish, and of an honeycomb, and he took it and did eat before them." },
      { q:"On the road to Emmaus, what did the unrecognized Jesus do?", choices:["Slept while they walked","Beginning at Moses and all the prophets, he expounded the things concerning himself","Healed one of them of blindness","Asked them for food and money"], a:1, why:"Beginning at Moses and all the prophets, he expounded unto them in all the scriptures the things concerning himself." },
      { q:"What did Jesus command before ascending from Bethany?", choices:["To sell everything and return to Galilee","To take up swords for defense","To tarry in Jerusalem until endued with power from on high","To build a temple on the mount of Olives"], a:2, why:"He told them to tarry in the city until they were endued with power from on high, and to be witnesses of these things." }
    ] } );
